<?php use App\Models\Ticket; ?>
<section class="ticket-heading"><a class="text-button" href="/list?project=<?= (int)$project['id'] ?>">← Revenir à la liste</a><div><span class="type-icon type-<?= e($ticket['type']) ?>"><?= $ticket['type']==='epic'?'ϟ':'✓' ?></span><span class="ticket-key"><?= e($ticket['key']) ?></span><span class="pill status-<?= e($ticket['status']) ?>"><?= e(Ticket::STATUSES[$ticket['status']]) ?></span><div class="toolbar-spacer"></div><button class="button subtle" data-copy="<?= e(url('/tickets/'.$ticket['id'])) ?>"><?= icon('link') ?>Copier le lien</button></div><h1><?= e($ticket['title']) ?></h1><?php if($ticket['archived']): ?><div class="notice">Ce ticket est archivé.<form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/archive"><?= csrf() ?><input type="hidden" name="restore" value="1"><button class="button subtle">Restaurer le ticket</button></form></div><?php endif; ?></section>
<div class="ticket-layout"><div class="ticket-main"><section class="panel ticket-edit-panel"><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>" class="stack"><?= csrf() ?><input type="hidden" name="version" value="<?= (int)$ticket['version'] ?>"><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><label>Résumé<input name="title" value="<?= e($ticket['title']) ?>" required maxlength="240"></label><label>Temps total estimé (heures)<input name="estimated_hours" inputmode="decimal" value="<?= e($ticket['estimated_hours']) ?>" placeholder="Ex. : 2,5" maxlength="9"><small>Durée de travail prévue pour cette tâche. Facultatif, deux décimales maximum.</small></label><label>Description<textarea name="description" rows="9" placeholder="L’essentiel et les détails utiles…"><?= e($ticket['description']) ?></textarea></label><div class="inline-fields"><label>État<select name="status"><?php foreach(Ticket::STATUSES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label><label>Type<select name="type"><?php foreach(Ticket::TYPES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['type']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><div class="inline-fields"><label>Personne assignée<select name="assignee_id"><option value="">Non assigné</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $ticket['assignee_id']===$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select></label><label>Priorité<select name="priority"><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['priority']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><div class="inline-fields"><label>Date de début<input type="date" name="start_date" value="<?= e($ticket['start_date']) ?>"></label><label>Échéance<input type="date" name="due_date" value="<?= e($ticket['due_date']) ?>"></label></div><label id="relations">Parent<select name="parent_id"><option value="">Aucun</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $ticket['parent_id']===$p['id']?'selected':'' ?>><?= e($project['project_key'].'-'.$p['number'].' · '.$p['title']) ?></option><?php endforeach; ?></select></label><label>Étiquettes<input name="labels" value="<?= e(implode(', ',$ticket['labels_array'])) ?>" placeholder="Séparées par une virgule"></label><label class="check-label"><input type="checkbox" name="flagged" value="1" <?= $ticket['flagged']?'checked':'' ?>>Ce ticket est bloqué</label><?php if($user['role']!=='viewer'): ?><button class="button primary">Enregistrer les modifications <?= icon('check') ?></button><?php endif; ?></form></section>
<section class="panel" id="activity"><h2>La conversation</h2><?php foreach($comments as $c): ?><article class="comment"><?= avatar($c['name'],'small') ?><div><strong><?= e($c['name']) ?></strong><small><?= e($c['created_at']) ?></small><p><?= nl2br(e($c['body'])) ?></p></div></article><?php endforeach; if(!$comments): ?><p class="muted">Le contexte est souvent le meilleur point de départ.</p><?php endif; if($user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/comments" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><textarea name="body" rows="3" maxlength="10000" placeholder="Une précision, une question, une avancée…" required></textarea><button class="button subtle">Ajouter un commentaire</button></form><?php endif; ?></section></div>
<aside class="ticket-aside"><section class="panel"><h3>Dans les détails</h3><dl class="ticket-meta"><dt>Projet</dt><dd><?= e($project['name']) ?></dd><dt>Rapporteur</dt><dd><?= e($ticket['reporter_name']??'Externe') ?></dd><dt>Créé le</dt><dd><?= e(substr($ticket['created_at'],0,16)) ?></dd><dt>Mis à jour le</dt><dd><?= e(substr($ticket['updated_at'],0,16)) ?></dd><?php if($ticket['external_email']): ?><dt>Contact externe</dt><dd><?= e($ticket['external_email']) ?></dd><?php endif; ?></dl></section>
<section class="panel"><h3>Pièces jointes</h3><?php foreach($attachments as $a): ?><a class="attachment" href="/attachments/<?= (int)$a['id'] ?>"><?= icon('download') ?><span><?= e($a['original_name']) ?><small><?= number_format($a['size_bytes']/1024,0,',',' ') ?> Ko</small></span></a><?php endforeach; if($user['role']!=='viewer'): ?><form method="post" enctype="multipart/form-data" action="/tickets/<?= (int)$ticket['id'] ?>/attachments" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><label class="small-upload">Ajouter un fichier<input type="file" name="file" required></label><button class="button subtle small-button">Joindre le fichier</button></form><?php endif; ?></section>
<section class="panel"><h3>Tickets liés</h3><?php foreach($links as $link): ?><div class="linked-ticket"><a href="/tickets/<?= (int)$link['target_id'] ?>"><small><?= e(['relates'=>'Associé à','blocks'=>'Bloque','duplicates'=>'Doublon de'][$link['relation']]) ?></small><?= e($link['project_key'].'-'.$link['number'].' · '.$link['title']) ?></a><?php if($user['role']!=='viewer'): ?><form method="post" action="/links/<?= (int)$link['id'] ?>/delete"><?= csrf() ?><button class="tiny-button" aria-label="Retirer la relation">×</button></form><?php endif; ?></div><?php endforeach; if($user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/links" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><select name="relation"><option value="relates">Associé à</option><option value="blocks">Bloque</option><option value="duplicates">Doublon de</option></select><select name="target_id" required><option value="">Choisir un ticket</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($project['project_key'].'-'.$p['number'].' · '.$p['title']) ?></option><?php endforeach; ?></select><button class="button subtle small-button">Associer</button></form><?php endif; ?></section>
<?php if($children): ?><section class="panel"><h3>Tickets enfants</h3><?php foreach($children as $child): ?><a class="child-ticket" href="/tickets/<?= (int)$child['id'] ?>"><span class="legend-dot status-<?= e($child['status']) ?>"></span><?= e($child['title']) ?></a><?php endforeach; ?></section><?php endif; ?>
<?php if($events): ?><section class="panel"><h3>Développement</h3><?php foreach($events as $event): ?><a class="child-ticket" href="<?= e($event['external_url']) ?>" target="_blank" rel="noopener"><?= icon('code') ?><?= e($event['title']) ?></a><?php endforeach; ?></section><?php endif; ?>
<?php if(!$ticket['archived']&&$user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/archive"><?= csrf() ?><button class="text-button danger" data-confirm="Archiver ce ticket ? Il restera accessible depuis sa fiche.">Archiver ce ticket</button></form><?php endif; ?></aside></div>
